/* Lot 112: line-height passed to the engine, rlh, all and revert (generated by scripts/lot112_gen.py; expectations from scripts/lot112_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];
static char g_o[512];
static char g_s[160];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(5, g_d.nnodes);
}

/* the line heights the reader keeps for body, #o and #i (px
 * thousandths + 1, 0 for normal) */
static const char *lh3(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d", g_d.lh[2], g_d.lh[3], g_d.lh[4]);
    return g_o;
}

/* the line-height part of the style passed for node i, - for none */
static void lhs_of(int i, char *t, int cap) {
    const char *h;
    int k = 0;
    g_o[0] = 0;
    wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    h = strstr(g_o, "line-height:");
    if (!h) { snprintf(t, cap, "-"); return; }
    while (h[k] && h[k] != ';' && h[k] != '"' && k < cap - 1) { t[k] = h[k]; k++; }
    t[k] = 0;
}

static const char *lhs3(void) {
    char a[48], b[48], c[48];
    lhs_of(2, a, (int)sizeof(a));
    lhs_of(3, b, (int)sizeof(b));
    lhs_of(4, c, (int)sizeof(c));
    snprintf(g_s, sizeof(g_s), "%s %s %s", a, b, c);
    return g_s;
}

/* the height (px) in the style passed for the element with that id,
 * -1 when it has none */
static int height_of(const char *id) {
    int i, v = -1;
    const char *h;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    h = strstr(g_o, ";height:");
    if (!h) h = strstr(g_o, "\"height:");
    if (h) sscanf(h + 8, "%d", &v);
    return v;
}

static void test_l112_lh_0(void) {
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { html { line-height: 200% } } @layer a { body { line-height: normal } } html { font-size: 20px } #o { line-height: min(2, 1.25); overflow: auto; height: calc(3rlh - 1em) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 25001 25001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:normal line-height:25px line-height:25px", lhs3());
    TEST_ASSERT_EQUAL(100, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { --v: 20px; line-height: unset } body { font-size: 24px; --v: calc(100% + 1px) } #o { line-height: auto; overflow: auto; height: 3lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL_STRING("- - -", lhs3());
    TEST_ASSERT_EQUAL(45, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } body { line-height: calc(3 / 2); line-height: 0.8 } html { --v: calc(1 + 1); line-height: var(--u) } #o { font-size: 1.5em; --v: auto; line-height: calc(1 + 0.5); line-height: normal; overflow: auto; height: 3lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("12801 0 0", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:12px line-height:normal line-height:normal", lhs3());
    TEST_ASSERT_EQUAL(45, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { html { line-height: 200% } } @layer a { #i { line-height: revert-layer } } #i { --v: auto } #o { font-size: 32px; line-height: clamp(10px, 125%, 30px); line-height: inherit; overflow: auto; height: calc(1rlh + 1lh) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("32001 32001 32001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:32px line-height:32px line-height:32px", lhs3());
    TEST_ASSERT_EQUAL(64, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { --v: 2rlh; line-height: normal } #o { line-height: unset; line-height: 45px; overflow: auto; height: calc(2lh + 10px) } html { line-height: clamp(10px, 125%, 30px); line-height: revert } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 45001 0", lh3());
    TEST_ASSERT_EQUAL_STRING("- line-height:40px line-height:normal", lhs3());
    TEST_ASSERT_EQUAL(100, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { #o { line-height: revert-layer } } #i { --v: 150%; line-height: 0.8; line-height: calc(50% + 0.5em) } html { --v: 20px; line-height: calc(10% * 3); line-height: 2lh } body { all: unset } #o { --v: auto; overflow: auto; height: max(2rlh, 30px) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20001 20001 16001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:20px line-height:20px line-height:16px", lhs3());
    TEST_ASSERT_EQUAL(40, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { html { line-height: 200% } } #i { line-height: min(150%, 30px) } html { --v: calc(100% + 1px); line-height: revert; line-height: 2rlh } #o { --v: 20px; line-height: calc(100% + 2px); overflow: auto; height: max(2rlh, 30px) } body { font-size: 1.5em } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20001 26001 30001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:20px line-height:26px line-height:30px", lhs3());
    TEST_ASSERT_EQUAL(40, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { body { line-height: 25px } } @layer a { #i { line-height: calc(1rlh + 5px) } } #o { line-height: 150%; line-height: 0.5; overflow: auto; height: 1lh } #i { font-size: 1.5em } body { line-height: 150% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("24001 8001 15001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:24px line-height:10px line-height:15px", lhs3());
    TEST_ASSERT_EQUAL(8, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { body { line-height: revert-layer } } @layer a { #i { line-height: revert-layer } } #o { line-height: 2lh; overflow: auto; height: 1lh } body { font-size: 20px; --v: 150%; line-height: calc(50% + 0.5em) } #i { line-height: calc(200% + 1rlh) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20001 40001 50001", lh3());
    TEST_ASSERT_EQUAL_STRING("line-height:20px line-height:40px line-height:40px", lhs3());
    TEST_ASSERT_EQUAL(40, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } @layer a { #i { line-height: 3 } } #o { overflow: auto; height: 1lh } #i { font-size: 24px; line-height: initial } html { --v: auto } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL_STRING("- - -", lhs3());
    TEST_ASSERT_EQUAL(10, height_of("o"));
}

